package com.nuvio.app.features.explore

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

/**
 * The curated Christmas Romance catalogue (BannerTV's own list of holiday romance films: Hallmark, Lifetime, Great
 * American Family, Netflix and others), matched to TMDB. Each film carries its network, premiere date, romance tropes
 * and whether it is an editorial pick, so the collection can be shown as shelves by network, trope and season.
 *
 * Rows: tmdbId | title | year | network | status | premiere | pick | tropes | holiday | poster | backdrop | date | vote | votes | language.
 */
internal object ChristmasRomanceCatalogue {
    private class Entry(
        val tmdbId: Int, val title: String, val year: Int, val network: String, val released: Boolean, val premiere: String,
        val pick: Boolean, val tropes: Set<String>, val holiday: String, val poster: String, val backdrop: String,
        val date: String, val vote: String, val votes: Int, val language: String,
    ) {
        /** When it came (or comes) out: the network's premiere date, else TMDB's. */
        val sortDate: String get() = premiere.ifBlank { date.ifBlank { "$year-01-01" } }

        /** A TMDB-shaped record, so the app's usual mapping turns it into a card. */
        fun toJson(): JsonObject = buildJsonObject {
            put("id", tmdbId)
            put("title", title)
            if (poster.isNotBlank()) put("poster_path", poster)
            if (backdrop.isNotBlank()) put("backdrop_path", backdrop)
            put("release_date", sortDate)
            put("vote_average", vote.toDoubleOrNull() ?: 0.0)
            put("vote_count", votes)
            if (language.isNotBlank()) put("original_language", language)
        }
    }

    private val entries: List<Entry> by lazy {
        RAW.mapNotNull { line ->
            val f = line.split('|')
            if (f.size < 15) return@mapNotNull null
            Entry(
                tmdbId = f[0].toIntOrNull() ?: return@mapNotNull null, title = f[1], year = f[2].toIntOrNull() ?: 0, network = f[3],
                released = f[4] != "upcoming", premiere = f[5], pick = f[6] == "1",
                tropes = f[7].split(',').filter { it.isNotBlank() }.toSet(), holiday = f[8], poster = f[9], backdrop = f[10],
                date = f[11], vote = f[12], votes = f[13].toIntOrNull() ?: 0, language = f[14],
            )
        }
    }

    private const val SHELF_LIMIT = 100
    private val OTHER_NETWORKS = setOf("Independent", "BET+", "International", "Prime Video", "Roku", "Other")

    /**
     * One shelf: "picks" (editorial favourites), "recent" (newest premieres), "upcoming" (not out yet), "network:<name>"
     * ("network:other" for the smaller networks and streamers), "trope:<tag>" and "holiday:hanukkah". Newest first, except
     * the upcoming shelf, which runs soonest first.
     */
    fun shelf(key: String): List<JsonObject> {
        val all = entries
        val out = when {
            key == "upcoming" -> all.filter { !it.released }.sortedBy { it.sortDate }
            key == "picks" -> all.filter { it.pick && it.released }.sortedWith(newest())
            key == "recent" -> all.filter { it.released && it.year >= 2025 }.sortedByDescending { it.sortDate }
            key == "network:other" -> all.filter { it.released && it.network in OTHER_NETWORKS }.sortedWith(newest())
            key.startsWith("network:") -> all.filter { it.released && it.network == key.removePrefix("network:") }.sortedWith(newest())
            key.startsWith("trope:") -> all.filter { it.released && key.removePrefix("trope:") in it.tropes }.sortedWith(newest())
            key == "holiday:hanukkah" -> all.filter { it.released && it.holiday.contains("Hanukkah") }.sortedWith(newest())
            else -> emptyList()
        }
        return out.take(SHELF_LIMIT).map { it.toJson() }
    }

    private fun newest() = compareByDescending<Entry> { it.year }.thenByDescending { it.votes }

